  "mcpUrl": "http://127.0.0.1:9791/mcp",
  "toolSchemas": [
    {
      "name": "animation_editor",
      "description": "Creates and modifies animations (state machines, linear animations, keyframes) on the active artboard. Falls back to the first artboard when none is activated; use query_core_object_tool.listArtboards to disambiguate. Special state names: \"{Entry State}\", \"{Any State}\". Between two keyframes the smaller-frame keyframe's interpolator (hold/linear/cubic/elastic) drives the curve. Commands: createStateMachine, createStateMachineLayers, createTransitions, createConditions, createLinearAnimations: create the named entity; createStates: Add new animation states to an EXISTING layer (use this when the layer already exists; createStateMachineLayers spawns a new layer instead); listStateMachines: id/name/layers only — for inspection use queryStateMachine; listLinearAnimations: all linear animations; queryStateMachine: PRIMARY read. Fully expands a state machine — layers with states/transitions/conditions/events/listenerActions, plus top-level inputs and listeners. View-model, event, and input refs are pre-resolved with names. Defaults to the only state machine; pass stateMachineId to disambiguate; queryStateMachineLayer: Re-read one layer (same per-layer payload); updateStates: Update existing states; renameAnimations: Rename animations; modifyKeyFrames: Add/delete/change keyframes; queryKeyFrames: Read keyframes; reverseKeyFrames: Reverse keyframes (scope: selection, else visible graph curves, else all). Data is passed under data.<command> or directly in data.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "enum": [
              "createStateMachine",
              "createLinearAnimations",
              "listStateMachines",
              "listLinearAnimations",
              "queryStateMachine",
              "queryStateMachineLayer",
              "createStateMachineLayers",
              "createStates",
              "updateStates",
              "createTransitions",
              "createConditions",
              "renameAnimations",
              "modifyKeyFrames",
              "queryKeyFrames",
              "reverseKeyFrames"
            ]
          },
          "data": {
            "type": "object",
            "properties": {
              "createStateMachine": {
                "type": "object",
                "properties": {
                  "name": {
                    "type": "string"
                  },
                  "layers": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "name": {
                          "type": "string"
                        },
                        "states": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "name": {
                                "type": "string"
                              },
                              "x": {
                                "type": "number"
                              },
                              "y": {
                                "type": "number"
                              },
                              "linearAnimationName": {
                                "type": "string"
                              },
                              "transitions": {
                                "type": "array",
                                "items": {
                                  "type": "object",
                                  "properties": {
                                    "from": {
                                      "type": "string"
                                    },
                                    "to": {
                                      "type": "string"
                                    }
                                  }
                                }
                              }
                            }
                          }
                        },
                        "otherTransitions": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "from": {
                                "type": "string"
                              },
                              "to": {
                                "type": "string"
                              }
                            }
                          }
                        }
                      }
                    }
                  },
                  "linearAnimations": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "name": {
                          "type": "string"
                        },
                        "duration": {
                          "type": "number"
                        }
                      }
                    }
                  }
                },
                "required": [
                  "name"
                ]
              },
              "createLinearAnimations": {
                "type": "object",
                "properties": {
                  "linearAnimations": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "name": {
                          "type": "string"
                        },
                        "duration": {
                          "type": "number"
                        }
                      }
                    }
                  }
                },
                "required": [
                  "linearAnimations"
                ]
              },
              "listStateMachines": {
                "type": "object",
                "properties": {}
              },
              "listLinearAnimations": {
                "type": "object",
                "properties": {}
              },
              "queryStateMachine": {
                "type": "object",
                "properties": {
                  "stateMachineId": {
                    "description": "Optional. Defaults to the only state machine in the active artboard.",
                    "type": "string"
                  }
                }
              },
              "queryStateMachineLayer": {
                "type": "object",
                "properties": {
                  "layerId": {
                    "type": "string"
                  }
                },
                "required": [
                  "layerId"
                ]
              },
              "createStateMachineLayers": {
                "type": "object",
                "properties": {
                  "stateMachineId": {
                    "type": "string"
                  },
                  "layers": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "name": {
                          "type": "string"
                        },
                        "states": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "name": {
                                "type": "string"
                              },
                              "x": {
                                "type": "number"
                              },
                              "y": {
                                "type": "number"
                              },
                              "linearAnimationName": {
                                "type": "string"
                              },
                              "transitions": {
                                "type": "array",
                                "items": {
                                  "type": "object",
                                  "properties": {
                                    "from": {
                                      "type": "string"
                                    },
                                    "to": {
                                      "type": "string"
                                    }
                                  }
                                }
                              }
                            }
                          }
                        },
                        "otherTransitions": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "from": {
                                "type": "string"
                              },
                              "to": {
                                "type": "string"
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                },
                "required": [
                  "stateMachineId",
                  "layers"
                ]
              },
              "createStates": {
                "type": "object",
                "properties": {
                  "layerId": {
                    "description": "ID of an existing state machine layer.",
                    "type": "string"
                  },
                  "states": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "name": {
                          "type": "string"
                        },
                        "x": {
                          "type": "number"
                        },
                        "y": {
                          "type": "number"
                        },
                        "linearAnimationName": {
                          "description": "Name of an existing linear animation on the artboard. If unresolvable, the state is still created but a warning is emitted.",
                          "type": "string"
                        },
                        "transitions": {
                          "description": "Inline transitions; from/to match state names declared in this same payload.",
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "from": {
                                "type": "string"
                              },
                              "to": {
                                "type": "string"
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                },
                "required": [
                  "layerId",
                  "states"
                ]
              },
              "updateStates": {
                "type": "object",
                "properties": {
                  "states": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "id": {
                          "type": "string"
                        },
                        "animationId": {
                          "type": "string"
                        },
                        "x": {
                          "type": "number"
                        },
                        "y": {
                          "type": "number"
                        }
                      }
                    }
                  }
                },
                "required": [
                  "states"
                ]
              },
              "createTransitions": {
                "type": "object",
                "properties": {
                  "states": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "id": {
                          "type": "string"
                        },
                        "transitions": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "to": {
                                "type": "string"
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                },
                "required": [
                  "states"
                ]
              },
              "createConditions": {
                "type": "object",
                "properties": {
                  "transitions": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "id": {
                          "type": "string"
                        },
                        "conditions": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "leftComparator": {
                                "type": "object",
                                "properties": {
                                  "viewModelPropertyId": {
                                    "type": "string"
                                  }
                                }
                              },
                              "comparationOperation": {
                                "type": "string",
                                "enum": [
                                  "equal",
                                  "notEqual",
                                  "largerThan",
                                  "smallerThan",
                                  "largerOrEqualTo",
                                  "smallerOrEqualTo"
                                ]
                              },
                              "rightComparator": {
                                "type": "object",
                                "properties": {
                                  "valueType": {
                                    "type": "string"
                                  },
                                  "value": {
                                    "type": "string"
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                },
                "required": [
                  "transitions"
                ]
              },
              "renameAnimations": {
                "type": "object",
                "properties": {
                  "animations": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "animationId": {
                          "type": "string"
                        },
                        "name": {
                          "type": "string"
                        }
                      }
                    }
                  }
                },
                "required": [
                  "animations"
                ]
              },
              "modifyKeyFrames": {
                "type": "object",
                "properties": {
                  "animationId": {
                    "type": "string"
                  },
                  "add": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "objectId": {
                          "type": "string"
                        },
                        "propertyKey": {
                          "type": "integer"
                        },
                        "frame": {
                          "type": "integer"
                        },
                        "value": {
                          "oneOf": [
                            {
                              "description": "for values that are double",
                              "type": "number"
                            },
                            {
                              "description": "for values that are colors, format is #aarrggbb",
                              "type": "string"
                            },
                            {
                              "type": "boolean"
                            }
                          ]
                        },
                        "interpolationType": {
                          "description": "The interpolation type for the keyframe to determine the value in between two keyframes:hold: hold the incoming value until the next keyframe is reached;linear: linearly interpolate;cubic: cubicly interpolate with parameters;",
                          "type": "string",
                          "enum": [
                            "hold",
                            "linear",
                            "cubic",
                            "elastic"
                          ]
                        },
                        "cubicParams": {
                          "description": "Parameters for cubic interpolation. x1, x2 in [0, 1], y1, y2 in [-1, 1]",
                          "type": "object",
                          "properties": {
                            "x1": {
                              "type": "number"
                            },
                            "y1": {
                              "type": "number"
                            },
                            "x2": {
                              "type": "number"
                            },
                            "y2": {
                              "type": "number"
                            }
                          }
                        },
                        "elasticParams": {
                          "description": "Parameters for elastic interpolation",
                          "type": "object",
                          "properties": {
                            "easing": {
                              "description": "0=easeIn, 1=easeOut, 2=easeInOut",
                              "type": "integer",
                              "enum": [
                                0,
                                1,
                                2
                              ]
                            },
                            "amplitude": {
                              "description": "A percentage of change, defaults to 1.0",
                              "type": "number"
                            },
                            "period": {
                              "description": "Percentage of time difference, defaults to 1.0",
                              "type": "number"
                            }
                          }
                        }
                      },
                      "required": [
                        "objectId",
                        "propertyKey",
                        "frame",
                        "value"
                      ]
                    }
                  },
                  "change": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "keyframeId": {
                          "type": "string"
                        },
                        "frame": {
                          "type": "integer"
                        },
                        "value": {
                          "oneOf": [
                            {
                              "description": "for values that are double",
                              "type": "number"
                            },
                            {
                              "description": "for values that are colors, format is #aarrggbb",
                              "type": "string"
                            },
                            {
                              "type": "boolean"
                            }
                          ]
                        },
                        "interpolationType": {
                          "description": "The interpolation type for the keyframe to determine the value in between two keyframes:hold: hold the incoming value until the next keyframe is reached;linear: linearly interpolate;cubic: cubicly interpolate with parameters;",
                          "type": "string",
                          "enum": [
                            "hold",
                            "linear",
                            "cubic",
                            "elastic"
                          ]
                        },
                        "cubicParams": {
                          "description": "Parameters for cubic interpolation. x1, x2 in [0, 1], y1, y2 in [-1, 1]",
                          "type": "object",
                          "properties": {
                            "x1": {
                              "type": "number"
                            },
                            "y1": {
                              "type": "number"
                            },
                            "x2": {
                              "type": "number"
                            },
                            "y2": {
                              "type": "number"
                            }
                          }
                        },
                        "elasticParams": {
                          "description": "Parameters for elastic interpolation",
                          "type": "object",
                          "properties": {
                            "easing": {
                              "description": "0=easeIn, 1=easeOut, 2=easeInOut",
                              "type": "integer",
                              "enum": [
                                0,
                                1,
                                2
                              ]
                            },
                            "amplitude": {
                              "description": "A percentage of change, defaults to 1.0",
                              "type": "number"
                            },
                            "period": {
                              "description": "Percentage of time difference, defaults to 1.0",
                              "type": "number"
                            }
                          }
                        }
                      },
                      "required": [
                        "keyframeId"
                      ]
                    }
                  },
                  "delete": {
                    "description": "List of keyframe IDs to delete",
                    "type": "array",
                    "items": {
                      "type": "string"
                    }
                  }
                },
                "required": [
                  "animationId"
                ]
              },
              "queryKeyFrames": {
                "type": "object",
                "properties": {
                  "animationIds": {
                    "description": "List of linear animation IDs to query. Defaults to the selected linear animation if not provided.",
                    "type": "array",
                    "items": {
                      "type": "string"
                    }
                  },
                  "selectedKeyFramesOnly": {
                    "description": "If true, returns only selected keyframes. Otherwise, get all keyframes in the specified animations.",
                    "type": "boolean"
                  }
                }
              },
              "reverseKeyFrames": {
                "type": "object",
                "properties": {
                  "animationId": {
                    "description": "Optional selected linear animation ID. Defaults to the selected linear animation when omitted.",
                    "type": "string"
                  }
                }
              }
            }
          }
        },
        "required": [
          "command"
        ]
      },
      "execution": {
        "taskSupport": "forbidden"
      }
    },
    {
      "name": "assets_tool",
      "description": "Read and instantiate assets (images, audio, fonts, scripts, libraries, components, blobs, svg, lottie). listAssets: Folder-grouped tree; queryAsset: One asset by id; addImageInstance: Spawn an Image shape from an ImageAsset; addImagesAsSolo: Spawn a Solo of Images (no input/VM wiring).",
      "inputSchema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "enum": [
              "listAssets",
              "queryAsset",
              "addImageInstance",
              "addImagesAsSolo"
            ]
          },
          "data": {
            "type": "object",
            "properties": {
              "listAssets": {
                "type": "object",
                "properties": {
                  "typeFilter": {
                    "description": "Optional. One of: image, audio, font, script, library, component, svg, lottie, file, folder, group, componentGroup. Folders are still walked.",
                    "type": "string"
                  }
                }
              },
              "queryAsset": {
                "type": "object",
                "properties": {
                  "assetId": {
                    "type": "string"
                  }
                },
                "required": [
                  "assetId"
                ]
              },
              "addImageInstance": {
                "type": "object",
                "properties": {
                  "assetId": {
                    "type": "string"
                  },
                  "parentId": {
                    "description": "Optional. Defaults to active artboard.",
                    "type": "string"
                  },
                  "name": {
                    "type": "string"
                  },
                  "x": {
                    "type": "number"
                  },
                  "y": {
                    "type": "number"
                  }
                },
                "required": [
                  "assetId"
                ]
              },
              "addImagesAsSolo": {
                "type": "object",
                "properties": {
                  "assetIds": {
                    "description": "ImageAsset IDs in display order.",
                    "type": "array",
                    "items": {
                      "type": "string"
                    }
                  },
                  "parentId": {
                    "description": "Optional. Defaults to active artboard.",
                    "type": "string"
                  },
                  "name": {
                    "type": "string"
                  },
                  "activeAssetId": {
                    "description": "Optional. Defaults to first.",
                    "type": "string"
                  },
                  "x": {
                    "type": "number"
                  },
                  "y": {
                    "type": "number"
                  }
                },
                "required": [
                  "assetIds"
                ]
              }
            }
          }
        },
        "required": [
          "command"
        ]
      },
      "execution": {
        "taskSupport": "forbidden"
      }
    },
    {
      "name": "component_editor",
      "description": "Adds Components to other Artboards. When a Component Artboard has a ViewModel bound, we should try to hook it up to the parent Artboard's ViewModel as a property. Supports commands like,addComponents: Adds a Component as a child of the given parent on the specified artboard; addComponentList: Adds a Component list container as a child of the given parent on the specified artboard where the parent determines the list's layout. A Component List automatically generates component instances at runtime based on the specified ViewModelPropertyList id so DO NOT manually add Components as children of the list. Use instead of 'addComponents' whenever a list of items is required; ",
      "inputSchema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "enum": [
              "addComponents",
              "addComponentList"
            ]
          },
          "data": {
            "type": "object",
            "properties": {
              "addComponents": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "artboardId": {
                      "description": "The ID of the artboard target",
                      "type": "string"
                    },
                    "artboardName": {
                      "description": "The name of the artboard target",
                      "type": "string"
                    },
                    "parentId": {
                      "description": "The ID of the object that should be the Components immediate parent",
                      "type": "string"
                    },
                    "componentId": {
                      "description": "The ID of the component to add to the artboard",
                      "type": "string"
                    },
                    "mode": {
                      "description": "The mode of the component to add which determines how it behaves when it resizes. node = stretches, leaf = scales with proportions, alignment, layout = does not scale, but resizes and reflows its internal layout contents",
                      "type": "string",
                      "enum": [
                        "node",
                        "leaf",
                        "layout"
                      ]
                    },
                    "widthScaleType": {
                      "description": "The width scale type of the component when in layout mode. fixed = fixed size, fill = fills its parent layout, hug = lets its children determine its size",
                      "type": "string",
                      "enum": [
                        "fixed",
                        "fill",
                        "hug"
                      ]
                    },
                    "heightScaleType": {
                      "description": "The height scale type of the component when in layout mode. fixed = fixed size, fill = fills its parent layout, hug = lets its children determine its size",
                      "type": "string",
                      "enum": [
                        "fixed",
                        "fill",
                        "hug"
                      ]
                    },
                    "x": {
                      "description": "The X position of the component in the artboard",
                      "type": "number"
                    },
                    "y": {
                      "description": "The Y position of the component in the artboard",
                      "type": "number"
                    }
                  }
                }
              },
              "addComponentList": {
                "type": "object",
                "properties": {
                  "artboardId": {
                    "description": "The ID of the artboard target",
                    "type": "string"
                  },
                  "artboardName": {
                    "description": "The name of the artboard target",
                    "type": "string"
                  },
                  "parentId": {
                    "description": "The ID of the object that should be the Components immediate parent",
                    "type": "string"
